// Builds the "Jogurt UI" resource pack (green menus, Jogurt logo, yogurt totem, hotbar) and enables it for a modpack.
// Textures live in assets/ingame (generated by tools/make_ingame_pack.py). The right set is picked per Minecraft version,
// because the title logo and button textures changed layout across versions.
const fs = require('fs');
const path = require('path');
const AdmZip = require('adm-zip');

const PACK_FILE = 'JogurtUI.zip';

/** What this Minecraft version needs. Snapshots and the year-based versions (26.x) count as modern. */
function era(version) {
  const m = String(version || '').match(/^(\d+)\.(\d+)(?:\.(\d+))?/);
  if (!m || +m[1] !== 1) return { flat: true, sprites: true, newLogo: true, format: 34, modern: true };
  const minor = +m[2], patch = +m[3] || 0;
  const sprites = minor >= 21 || (minor === 20 && patch >= 2); // GUI sprites + nine-slice (1.20.2+)
  const newLogo = minor >= 20;                                   // single-row title logo (1.20+)
  const flat = minor >= 13;                                      // namespaced "file/..." pack ids
  let format = 1;
  if (minor >= 21) format = 34;
  else if (minor === 20) format = patch >= 5 ? 32 : patch >= 3 ? 22 : patch === 2 ? 18 : 15;
  else if (minor === 19) format = patch >= 4 ? 13 : patch === 3 ? 12 : 9;
  else if (minor === 18) format = 8; else if (minor === 17) format = 7;
  else if (minor === 16) format = patch >= 2 ? 6 : 5; else if (minor === 15) format = 5;
  else if (minor >= 13) format = 4; else if (minor >= 11) format = 3; else if (minor >= 9) format = 2;
  return { flat, sprites, newLogo, format, modern: sprites };
}

function mcmeta(e) {
  const pack = { description: '§aJogurt Client Totem\n§7Yogurt cup totem of undying + UI', pack_format: e.format };
  if (e.sprites) {
    // Declared compatible with every newer version so the game never flags it as outdated.
    pack.pack_format = 34;
    pack.supported_formats = { min_inclusive: 18, max_inclusive: 999 };
    pack.min_format = 18; pack.max_format = 999;
  }
  return JSON.stringify({ pack }, null, 2);
}

function addDir(zip, dir, into = '') {
  if (!fs.existsSync(dir)) return;
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name), rel = into ? into + '/' + name : name;
    if (fs.statSync(full).isDirectory()) addDir(zip, full, rel);
    else zip.addFile(rel, fs.readFileSync(full));
  }
}

function buildPack(assetsDir, version) {
  const e = era(version), zip = new AdmZip();
  zip.addFile('pack.mcmeta', Buffer.from(mcmeta(e)));
  const icon = path.join(assetsDir, 'pack.png');
  if (fs.existsSync(icon)) zip.addFile('pack.png', fs.readFileSync(icon));
  addDir(zip, path.join(assetsDir, 'common'));
  addDir(zip, path.join(assetsDir, e.sprites ? 'modern' : 'legacy'));
  addDir(zip, path.join(assetsDir, e.newLogo ? 'logo_new' : 'logo_old'));
  return zip.toBuffer();
}

/** Adds or removes the pack in options.txt, keeping everything else the player has set. */
function setEnabled(gameDir, on, e) {
  const f = path.join(gameDir, 'options.txt');
  const exists = fs.existsSync(f);
  if (!exists && !on) return;
  const lines = exists ? fs.readFileSync(f, 'utf8').split(/\r?\n/) : [];
  const id = e.flat ? 'file/' + PACK_FILE : PACK_FILE;
  const i = lines.findIndex(l => l.startsWith('resourcePacks:'));
  let list = e.flat ? ['vanilla'] : [];
  if (i >= 0) { try { const j = JSON.parse(lines[i].slice('resourcePacks:'.length)); if (Array.isArray(j)) list = j; } catch {} }
  list = list.filter(x => x !== 'file/' + PACK_FILE && x !== PACK_FILE);
  if (on) { const at = list.indexOf('vanilla'); list.splice(at >= 0 ? at + 1 : list.length, 0, id); } // above vanilla, below the player's own packs
  const line = 'resourcePacks:' + JSON.stringify(list);
  if (i >= 0) lines[i] = line;
  else { while (lines.length && lines[lines.length - 1] === '') lines.pop(); lines.push(line, ''); }
  fs.writeFileSync(f, lines.join('\n'));
}

/** Call before every launch. */
function install({ assetsDir, gameDir, version, enabled }) {
  const e = era(version), dir = path.join(gameDir, 'resourcepacks'), file = path.join(dir, PACK_FILE);
  if (enabled) { fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(file, buildPack(assetsDir, version)); }
  else { try { fs.unlinkSync(file); } catch {} }
  setEnabled(gameDir, enabled, e);
}

module.exports = { install, buildPack, era, mcmeta, setEnabled, PACK_FILE };
